function csvCell(v){
  if(v===null||v===undefined) return '';
  var s=(typeof v==='object')?JSON.stringify(v):String(v);
  if(/[",\n\r]/.test(s)) return '"'+s.replace(/"/g,'""')+'"';
  return s;
}
function jsonToCsv(json){
  var rows=Array.isArray(json)?json:[json];
  if(!rows.length) return '';
  var headers={};
  rows.forEach(function(r){ if(r&&typeof r==='object') Object.keys(r).forEach(function(k){headers[k]=1;}); });
  var hs=Object.keys(headers);
  var out=[hs.map(csvCell).join(',')];
  rows.forEach(function(r){ out.push(hs.map(function(k){return csvCell(r?r[k]:'');}).join(',')); });
  return out.join('\n');
}
